// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // 1. set up the scenario
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        // 2. deposit 1 ether
        c.deposit{value: 1 ether}();
        // now withdraw all
        vm.prank(user);
        c.withdrawAll();
        // 3. assert that balance (public getter) is 0 for the reference and 1 ether for the bug
        assertTrue(c.balance() == 0, "balance should be 0 after withdrawal");
    }
}

